insert into public.site_settings (id, business_name, tagline, established_year, phones, whatsapp, email, address, map_embed_url, instagram_url, facebook_url, seo_title, seo_description)
insert into public.elements (slug, name, sanskrit, tagline, description, image_url, image_alt, sort) values ('earth', 'Earth', 'Prithvi', 'What holds you', 'Grounding materials underfoot and around you: floors of wood and stone-like vinyl, rugs that soften a room, and furniture built to stay.', '/images/brochure/wooden-flooring.webp', 'Warm wooden flooring beside a rustic console', 1) on conflict (slug) do nothing;
insert into public.elements (slug, name, sanskrit, tagline, description, image_url, image_alt, sort) values ('water', 'Water', 'Jal', 'What restores you', 'Rest and renewal: mattresses, bed linen and bath textiles chosen for softness, freshness and a good night''s sleep.', '/images/brochure/bed-bath-towels.webp', 'Folded soft towels with hydrangea on fresh bed linen', 2) on conflict (slug) do nothing;
insert into public.elements (slug, name, sanskrit, tagline, description, image_url, image_alt, sort) values ('fire', 'Fire', 'Agni', 'What warms you', 'Warmth and glow: lighting, rich upholstery and the decorative accents that give a room its personality.', '/images/brochure/fabric-lamps.webp', 'Three pleated fabric pendant lamps glowing warmly', 3) on conflict (slug) do nothing;
insert into public.elements (slug, name, sanskrit, tagline, description, image_url, image_alt, sort) values ('air', 'Air', 'Vayu', 'What lets you breathe', 'Light and air in balance: sheer and blackout curtains, blinds and motorised window systems that shape how a room feels through the day.', '/images/brochure/curtains-sheer.webp', 'Floor-length sheer curtains filtering daylight into a living room', 4) on conflict (slug) do nothing;
insert into public.elements (slug, name, sanskrit, tagline, description, image_url, image_alt, sort) values ('space', 'Space', 'Akasha', 'What surrounds you', 'The envelope of a room: wallpapers, wall panelling, glass films and the finishes that define the space itself.', '/images/brochure/art-decor-lounge.webp', 'Textured concrete wall with bronze sconces above a fluted cabinet', 5) on conflict (slug) do nothing;
insert into public.sectors (slug, name, tagline, summary, body, highlights, image_url, image_alt, sort) values ('home', 'Home Furnishings', 'Where every corner tells a story.', 'Sofas, beds, curtains and more, designed to bring warmth and character to your living spaces.', null, '[{"title":"Curtains & blinds","text":"Blackout, sheer and motorised options, measured and fitted by our team."},{"title":"Flooring","text":"Wooden, herringbone, SPC and vinyl floors with quick, clean installation."},{"title":"Bedroom","text":"Mattresses, bed-backs, linen and duvets for better rest."},{"title":"Walls","text":"Wallpapers, murals and wall panelling to set the tone of a room."}]'::jsonb, '/images/brochure/sector-home.webp', 'Bright living room with a cream sofa and panelled walls', 1) on conflict (slug) do nothing;
insert into public.sectors (slug, name, tagline, summary, body, highlights, image_url, image_alt, sort) values ('hospitality', 'Hotels & Restaurants', 'Affordable opulence, uncompromising comfort.', 'Elegant furnishings for hotels, restaurants, banquets and other commercial spaces.', null, '[{"title":"Wall-to-wall carpets","text":"Designer and corporate patterns for banquets, lobbies, suites and boardrooms."},{"title":"Room linen","text":"Bedsheets, duvets, mattress protectors and bath linen in hotel grades."},{"title":"Table linen","text":"Linens and overlays that dress up every event."},{"title":"Window solutions","text":"Blackout curtains and blinds for guest rooms."}]'::jsonb, '/images/brochure/sector-hospitality.webp', 'Hotel room with dark wood panelling and a chandelier', 2) on conflict (slug) do nothing;
insert into public.sectors (slug, name, tagline, summary, body, highlights, image_url, image_alt, sort) values ('healthcare', 'Healthcare', 'Caring for your space, caring for you.', 'Functional, hygienic and durable solutions for hospitals, from procurement to installation at a reasonable price.', null, '[{"title":"Healthcare flooring","text":"Homogeneous, conductive and heterogeneous PVC flooring for ICU, OPD and more."},{"title":"Hospital curtains & tracks","text":"Quick, easy installation at your doorstep."},{"title":"Hospital mattresses & pillows","text":"Customised to your dimensions and requirements."},{"title":"Anti-bacterial wallpapers","text":"Special wallcoverings made for healthcare settings."},{"title":"Window solutions","text":"Vertical, roller and sheer dimout blinds."},{"title":"Hygienic mats","text":"Exterior, interior, anti-skid and bath mats."},{"title":"Bedsheets & blankets","text":"Durable, comfortable options for patient care."},{"title":"Glass films","text":"Heat control and design for plain glass surfaces."}]'::jsonb, '/images/brochure/sector-healthcare.webp', 'Hospital ward with privacy curtains and patient beds', 3) on conflict (slug) do nothing;
insert into public.sectors (slug, name, tagline, summary, body, highlights, image_url, image_alt, sort) values ('education', 'Institutions & Education', 'Inspiring minds, igniting passion.', 'Furnishing solutions for schools, colleges, coaching institutes and universities that support learning and collaboration.', null, '[{"title":"Flooring","text":"Classroom and gym flooring, carpets and carpet tiles for auditoriums and cabins."},{"title":"Sports flooring","text":"For playing areas, tennis and badminton courts."},{"title":"Window solutions","text":"Room-darkening, light-filtering and acoustic blinds."},{"title":"Wallcoverings","text":"From budget-friendly to niche, plus digital murals for play areas and libraries."},{"title":"Wall panelling","text":"For smart classes and music rooms."},{"title":"Green turf & green walls","text":"For aesthetics and everyday use."},{"title":"Glass films","text":"Frosted, reflective, printed and PVC."},{"title":"Heat insulation & corporate gifting","text":"Roofing insulation and gifting for institutions."}]'::jsonb, '/images/brochure/sector-institutions.webp', 'Lecture hall with rows of chairs and a projection screen', 4) on conflict (slug) do nothing;
insert into public.sectors (slug, name, tagline, summary, body, highlights, image_url, image_alt, sort) values ('office', 'Office & Industrial', 'Productivity perfected, spaces optimised.', 'Ergonomic furniture and furnishings for productivity and comfort in the workplace.', null, '[{"title":"Carpet tiles","text":"Hard-wearing, easy to replace, quiet underfoot."},{"title":"Blinds","text":"Roller and vertical blinds for glare-free work."},{"title":"Glass films","text":"Privacy and branding for cabins and partitions."},{"title":"Anti-static & PVC stud flooring","text":"For server rooms, ramps, parking and entrances."}]'::jsonb, '/images/brochure/sector-office.webp', 'Executive office with bookshelves and a sculptural desk', 5) on conflict (slug) do nothing;
insert into public.sectors (slug, name, tagline, summary, body, highlights, image_url, image_alt, sort) values ('art-decor', 'Art & Decor', 'Beauty that inspires, spaces that delight.', 'Decorative accents and unique pieces that add a touch of personality to any space.', null, '[{"title":"Lighting","text":"Fabric lamps and statement pieces for serene spaces."},{"title":"Cushions & runners","text":"A pop of colour and texture for sofas and beds."},{"title":"Accent furniture","text":"Consoles, tea tables and carved wooden partitions (jharokhas)."}]'::jsonb, '/images/brochure/sector-art-decor.webp', 'Calm lounge with two armchairs, a floor lamp and a low table', 6) on conflict (slug) do nothing;
