insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('home', 'hero', 'Home: hero', 'Patna · Since 1984', 'Your home, your story.', 'Curtains, floors, walls, furniture and everything in between, chosen with you and fitted by our own team for over four decades.', '/images/brochure/hero-bedroom.webp', 'Sunlit bedroom with a rust velvet bed and sheer curtains', 'Explore products', '/products', '[]'::jsonb, 1) on conflict (page, key) do nothing;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('home', 'story', 'Home: story strip', '40+ years', 'Furnishing relationships, not just rooms.', 'What began as a furnishing shop in Patna in 1984 now serves homes, hotels, hospitals, schools and offices across Bihar, from the first measurement to the final installation.', null, null, null, null, '[{"title":"1984","text":"Established in Patna"},{"title":"40+","text":"Years of craft"},{"title":"6","text":"Sectors served"},{"title":"1","text":"Team, measurement to installation"}]'::jsonb, 2) on conflict (page, key) do nothing;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('home', 'philosophy', 'Home: philosophy teaser', 'Our philosophy', 'Every home is made of five elements.', 'Earth, water, fire, air and space. We furnish each one, so the whole house feels in balance.', null, null, 'Read our philosophy', '/philosophy', '[]'::jsonb, 3) on conflict (page, key) do nothing;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('home', 'categories', 'Home: categories heading', 'What we do', 'One house for everything your space needs.', null, null, null, 'All products', '/products', '[]'::jsonb, 4) on conflict (page, key) do nothing;
