insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('home', 'cta', 'Home: enquiry banner', null, 'Let''s create your dream space together.', 'Tell us about your space. We''ll visit, measure and suggest options that fit your budget.', '/images/brochure/why-dining.webp', 'Dining corner with ceramic pendant lamps', 'Make an enquiry', '/contact', '[]'::jsonb, 6) on conflict (page, key) do nothing;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('about', 'intro', 'About: introduction', 'About us', 'Home is where the heart finds its haven.', 'At New Ankur Furnishers, our passion is to create spaces that exude comfort, style and warmth, making every moment spent with loved ones truly unforgettable.
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('about', 'why', 'About: why choose us', null, 'Why choose us', null, '/images/brochure/why-dining.webp', 'Dining corner with ceramic pendant lamps', null, null, '[{"title":"Quality craftsmanship","text":"Every piece is crafted with precision and care."},{"title":"Innovative designs","text":"Contemporary, stylish designs that keep you ahead."},{"title":"Customer-centric approach","text":"We put your needs and preferences first."},{"title":"Industry expertise","text":"40+ years and a skilled team, so every project is executed with precision."}]'::jsonb, 2) on conflict (page, key) do nothing;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('about', 'founder', 'About: founder''s note', 'From our founder', '40+ years of furnishing relationships.', 'For us, a home is not just a place but a feeling, where the presence of loved ones becomes comfort, where relationships breathe, where happiness blossoms and dreams take shape.
